\draw (0,-0.5) arc (-90:-40:0.5);
\draw (0,-0.85) arc (-90:-140:0.85);
\node at (65:1.15) {$a^{\circ}$};
\node at (115:1.15) {$a^{\circ}$};
\node at (-65:1.15) {$a^{\circ}$};
\node at (-115:1.15) {$a^{\circ}$};
\node[align=center] at (40:2.35) {$\text{N}a^{\circ}\text{E}$\\$=a^{\circ}$};
\node[align=center] at (-40:2.35) {$\text{S}a^{\circ}\text{E}$\\$=180^{\circ}-a^{\circ}$};
